/**
 * @distilled.cloud/s2 — S2 (s2.dev, the durable streams API) SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models in
 * `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * document mirrored at `specs/spec-mirror-s2/specs/openapi.json`). Everything
 * else in this folder is hand-written.
 *
 * One module per S2 API tag: `accessTokens`, `basins`, `locations`,
 * `metrics` (account endpoint) and `streams`, `records` (basin endpoint —
 * configure `basin` on the credentials to call them).
 *
 * The SDK covers the REST surface only: `read` long-polls with `wait`, but
 * the Server-Sent Events streaming form of `read` and the S2S/protobuf
 * append protocol are not modeled — they live outside the OpenAPI
 * description.
 *
 * @example
 * ```ts
 * import * as S2 from "@distilled.cloud/s2";
 *
 * const { streams } = yield* S2.Services.streams.listStreams({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { S2Protocol, type S2OpError, type S2OpContext } from "./protocol.ts";
export { paginateStartAfter } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
